"""Generate a compact-state motion specialization from the unchanged physics body."""
from pathlib import Path
root=Path(__file__).resolve().parents[1]
s=(root/'src/simulator/scalable_junction_simulator.cu').read_text();start=s.index('__global__ void advance(');end=s.index('// Deterministic junction arbitration',start);kernel=s[start:end].split('#include "../../tools/compact_motion.cuh"')[0]
fields=[('int',x) for x in ['state','k','n','mid','event','denial']]+[('float',x) for x in ['departure','pos','v','stopped','entryWait']]+[('int',x) for x in ['edge','lane','movement']]
lines=['// Generated by tools/build_compact_motion.py; physics is copied, not rewritten.','#pragma once','struct MotionCar {']+[f' {typ} {name};' for typ,name in fields]+['};','struct CompactState { float* values; int count;',' __device__ MotionCar load(int i) const { MotionCar c;']
for j,(typ,name) in enumerate(fields):lines.append(f' c.{name}='+ (f'__float_as_int(values[{j}*count+i]);' if typ=='int' else f'values[{j}*count+i];'))
lines+=[' return c; }',' __device__ void store(int i,const MotionCar& c) const {']
for j,(typ,name) in enumerate(fields):lines.append(f' values[{j}*count+i]='+ (f'__int_as_float(c.{name});' if typ=='int' else f'c.{name};'))
lines+=[' }','};','__global__ void extractCompact(const Car* cars, CompactState out) { int i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=out.count)return;const Car& a=cars[i];MotionCar c;']
for typ,name in fields[:11]:lines.append(f' c.{name}=a.{name};')
lines+=[' c.edge=a.edges[a.k];c.lane=a.lanes[a.k];c.movement=a.moves[a.k];out.store(i,c);}', '__device__ void writeCompact(Car& dst,const MotionCar& c) {']
for typ,name in fields[:11]:lines.append(f' dst.{name}=c.{name};')
lines+=['}']
kernel=kernel.replace('__global__ void advance(const Car* old','__global__ void advanceCompact(CompactState old')
kernel=kernel.replace('next[i]=old[i];','writeCompact(next[i],old.load(i));').replace('Car c=old[i];','MotionCar c=old.load(i);').replace('const Car& d=old[leaders[i]];','const MotionCar d=old.load(leaders[i]);').replace('const Car& d=old[j];','const MotionCar d=old.load(j);').replace('next[i]=c;','writeCompact(next[i],c);')
for var in ['c','d']:
 for array,name in [('edges','edge'),('lanes','lane'),('moves','movement')]:kernel=kernel.replace(f'{var}.{array}[{var}.k]',f'{var}.{name}')
lines.append(kernel)
(root/'tools/compact_motion.cuh').write_text('\n'.join(lines))
